const soundedReminders=new Set();
const reminderSound=new Audio('reminder.wav');reminderSound.volume=0.65;
function playNewReminderSound(items){const fresh=items.filter(e=>!soundedReminders.has(e.id+'@'+e.startAt));if(!fresh.length)return;fresh.forEach(e=>soundedReminders.add(e.id+'@'+e.startAt));reminderSound.currentTime=0;reminderSound.play().catch(()=>{document.querySelector('#error').textContent=OrbitI18n.text('提示音无法播放，请检查系统音量。',presentation.language);});}
let events=[],presentation={language:'en',timeZone:'Asia/Shanghai'};
function render(){const root=document.querySelector('#items');root.replaceChildren();for(const e of events){const item=document.createElement('section');item.className='event';const remaining=Math.ceil((Date.parse(e.startAt)-Date.now())/60000);const countdown=document.createElement('div');countdown.className='countdown';countdown.textContent=remaining>0?remaining+' 分钟后开始':'日程已开始';const title=document.createElement('h2');title.textContent=e.title;title.dataset.userContent='';const detail=document.createElement('p');detail.textContent=e.date+' '+e.time+(e.location?' · '+e.location:'');item.append(countdown,title,detail);if(e.zoomLink){for(const [action,label,style] of [['zoom','加入 Zoom',''],['zoom-browser','应用内加入','secondary']]){const button=document.createElement('button');button.dataset.action=action;button.dataset.id=e.id;button.className=style;button.textContent=label;item.append(button);}}detail.dataset.userContent='';root.append(item);}OrbitI18n.apply(document.body,presentation.language);}
async function update(){[events,presentation]=await Promise.all([window.orbitReminder.getItems(),window.orbitReminder.getSettings()]);presentation=presentation||{language:'en'};render();playNewReminderSound(events);}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const result=await window.orbitReminder.action(button.dataset.action,button.dataset.id);document.querySelector('#error').textContent=result?.ok===false?OrbitI18n.text(result.error,presentation.language):'';});
window.orbitReminder.onUpdate(update);update();setInterval(render,15000);
